      WordNet.lookup(synset, (err, results) => {
        if (err) {
          reject(err);
        } else {
          const hyponyms = results.filter(result => result.ptrs.some(ptr => ptr.rel === 'hyponym'));
          this.cache[synset] = hyponyms;
          resolve(hyponyms);
