    const filteredTokens = this.removeStopwords(tokens);
    const stemmedTokens = this.stemTokens(filteredTokens);
    const contextualTokens = stemmedTokens.reduce((acc, token) => {
      acc[token] = (acc[token] || 0) + 1;
      return acc;
    }, {});
    return contextualTokens;
