  getSynonyms(token) {
    if (this.cache[token]) {
      return this.cache[token];
    }
    const synonyms = this.wordnet.lookup(token);
    this.cache[token] = synonyms;
    return synonyms;
  }

  getHyponyms(token) {
    if (this.cache[token + '_hyponyms']) {
      return this.cache[token + '_hyponyms'];
